import{CATALOGUE,DEPARTMENTS,LIMITS,IDX,decode,sum,ratio,department,select,group,getMetrics,getTrend,modelRates,previousMonth,week,alertRules}from'./engine.js';
const $=id=>document.getElementById(id), nf=new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}),fmt=n=>nf.format(n),pct=n=>n===null?'—':n.toFixed(2)+'%',escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const VIEWS={resumen:['Resumen','Resumen de calidad','Producción y segundas del producto terminado'],segundas:['Segundas','Segundas Costura','Análisis del producto terminado por modelo, color y defecto'],crudo:['Crudo','Segundas Crudo','Observaciones de crudo por modelo, defecto, turno y telar'],tejido:['Tejido','Calidad de Tejido','Defectos de producto terminado atribuibles a Tejido'],tintoreria:['Tintorería','Calidad de Tintorería','Defectos de producto terminado atribuibles a Tintorería'],costura:['Costura','Calidad de Costura','Defectos de producto terminado atribuibles a Costura']};
let data={},audit,view=Object.keys(VIEWS).includes(location.hash.slice(1))?location.hash.slice(1):'resumen',filters={period:'2026-09'},page=0,granularity='day',current,prior;
const fieldLabels={period:'Periodo',model:'Modelo',size:'Tamaño',color:'Color',defect:'Defecto',department:'Departamento',turn:'Turno',locality:'Localidad / Telar',salon:'Salón'};
const monthLabel=s=>!s||s==='all'?'Todo el histórico':s.includes('..')?s.split('..').map(monthLabel).join(' – '):new Date(s+'-01T12:00:00Z').toLocaleDateString('es-MX',{month:'long',year:'numeric',timeZone:'UTC'});
const fixedDepartment=()=>({tejido:'TEJIDO',tintoreria:'TINTORERÍA',costura:'COSTURA'}[view]);
const allBase=()=>view==='crudo'?data.crudo:data.seconds;
const effective=(f=filters)=>({...f,...(fixedDepartment()?{department:fixedDepartment()}: {})});
const fields=()=>view==='crudo'?['period','model','defect','turn','locality','salon']:['period','model','size','color','defect',...(fixedDepartment()?[]:['department'])];
function nav(){ $('nav-items').innerHTML=Object.entries(VIEWS).filter(([k])=>k!=='cargas').map(([k,v])=>`<button data-view="${k}" class="${view===k?'active':''}" ${view===k?'aria-current="page"':''}>${v[0]}</button>`).join('');}
function setPeriod(period){filters={period};granularity=period==='all'||period.includes('..')?'month':'day';page=0;render();}
function timelineUi(){
 const months=[...new Set(allBase().map(r=>r[0].slice(0,7)))].sort();
 const bounds=filters.period==='all'?[months[0],months.at(-1)]:filters.period.split('..');
 const from=Math.max(0,months.indexOf(bounds[0])),to=Math.max(from,months.indexOf(bounds[1]||bounds[0]));
 return `<div class="timeline"><div class="timeline-heading"><div><span class="timeline-label">Periodo</span><strong id="timeline-selection">${escape(monthLabel(filters.period))}</strong></div><button type="button" class="button timeline-all" id="timeline-all" aria-pressed="${filters.period==='all'}">Todo el histórico</button></div><div class="timeline-scroll"><div class="timeline-months" role="group" aria-label="Meses del histórico">${months.map((m,i)=>`<button type="button" data-month="${m}" class="timeline-month ${i>=from&&i<=to?'selected':''}" aria-pressed="${i>=from&&i<=to}" aria-label="${escape(monthLabel(m))}"><span>${new Date(m+'-01T12:00:00Z').toLocaleDateString('es-MX',{month:'short',timeZone:'UTC'})}</span><small>${m.slice(0,4)}</small></button>`).join('')}</div></div><div class="timeline-range"><label for="timeline-from">Desde <input id="timeline-from" type="range" min="0" max="${months.length-1}" step="1" value="${from}" aria-valuetext="${escape(monthLabel(months[from]))}"></label><label for="timeline-to">Hasta <input id="timeline-to" type="range" min="0" max="${months.length-1}" step="1" value="${to}" aria-valuetext="${escape(monthLabel(months[to]))}"></label></div></div>`;
}
function filterUi(){
 let preceding=effective({period:filters.period});
 const html=fields().filter(k=>k!=='period').map(k=>{const rows=select(allBase(),preceding),opts=[...new Set(rows.map(r=>k==='department'?department(r):(r[IDX[k]]||'__missing__')))].sort((a,b)=>a.localeCompare(b,'es'));if(filters[k]&&!opts.includes(filters[k]))delete filters[k];const selected=filters[k]||'';preceding[k]=selected;return `<div class="field"><label for="filter-${k}">${fieldLabels[k]}</label><select id="filter-${k}" data-filter="${k}"><option value="">Todos</option>${opts.map(o=>`<option value="${escape(o)}"${selected===o?' selected':''}>${escape(o==='__missing__'?'Sin dato':o)}</option>`).join('')}</select></div>`;}).join('');
 $('filters').innerHTML=timelineUi()+html+'<button class="clear" id="clear-filters">Limpiar filtros</button>';
 document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('change',e=>{const k=e.target.dataset.filter,keys=fields(),index=keys.indexOf(k);filters[k]=e.target.value;for(const x of keys.slice(index+1))delete filters[x];page=0;render();}));
 const months=[...new Set(allBase().map(r=>r[0].slice(0,7)))].sort(),from=$('timeline-from'),to=$('timeline-to');
 const bounds=()=>{let a=+from.value,b=+to.value;return[a,b];};
 function preview(which){if(+from.value>+to.value){if(which==='from')to.value=from.value;else from.value=to.value;}const[a,b]=bounds();from.setAttribute('aria-valuetext',monthLabel(months[a]));to.setAttribute('aria-valuetext',monthLabel(months[b]));$('timeline-selection').textContent=monthLabel(a===b?months[a]:months[a]+'..'+months[b]);document.querySelectorAll('[data-month]').forEach((el,i)=>{el.classList.toggle('selected',i>=a&&i<=b);el.setAttribute('aria-pressed',String(i>=a&&i<=b));});}
 for(const [el,name]of[[from,'from'],[to,'to']]){el.addEventListener('input',()=>preview(name));el.addEventListener('change',()=>{preview(name);const[a,b]=bounds();setPeriod(a===b?months[a]:months[a]+'..'+months[b]);});}
 document.querySelectorAll('[data-month]').forEach(el=>el.addEventListener('click',e=>{const m=el.dataset.month;if(e.shiftKey&&filters.period!=='all'){const anchor=filters.period.split('..')[0];setPeriod([anchor,m].sort().join('..'));}else setPeriod(m);}));
 $('timeline-all').onclick=()=>setPeriod('all');$('clear-filters').onclick=()=>setPeriod('all');
}
function kpi(label,value,target,qty,rate){const status=rate===null?'Sin denominador':rate>target?'Límite excedido':'Dentro del límite';return`<article class="kpi"><div class="kpi-head"><span class="kpi-label">${label}</span><span class="target">Meta ≤ ${target.toFixed(2)}%</span></div><div class="kpi-value">${value===null?'—':value.toFixed(2)+'<small>%</small>'}</div><div class="kpi-meta">${fmt(qty)} segundas</div><span class="status ${rate===null?'neutral':rate<=target?'good':''}">${status}</span></article>`;}
function countCard(label,value,meta){return`<article class="kpi"><div class="kpi-head"><span class="kpi-label">${label}</span></div><div class="kpi-value">${fmt(value)}</div><div class="kpi-meta">${meta}</div></article>`;}
function renderKpis(crudo){if(crudo){$('kpis').innerHTML=countCard('Cantidad reportada',current.total,'Suma del campo Cantidad del Excel')+countCard('Observaciones',current.rows.length,'Filas de defectos en crudo')+countCard('Modelos',new Set(current.rows.map(r=>r[1])).size,'Modelos en el segmento')+countCard('Localidades / Telares',new Set(current.rows.map(r=>r[11]).filter(Boolean)).size,'Localidades con observaciones');return;}
 const fixed=fixedDepartment();if(fixed){const unclassified=getMetrics(data.seconds,data.production,{...filters,department:'SIN CLASIFICAR'});$('kpis').innerHTML=kpi(fixed,current.rate,LIMITS[fixed],current.total,current.rate)+countCard('Segundas del proceso',current.total,'Departamento según catálogo maestro')+countCard('Producción del segmento',current.den,'Costura + Maquila, mismo periodo y dimensiones')+countCard('Departamento pendiente',unclassified.total,'Separadas del resultado de este proceso');}else $('kpis').innerHTML=kpi('Segundas Global',current.rate,1.6,current.total,current.rate)+['TEJIDO','TINTORERÍA','COSTURA'].map(d=>kpi(d,ratio(current.byDepartment[d],current.den),LIMITS[d],current.byDepartment[d],ratio(current.byDepartment[d],current.den))).join('');}
function renderProduction(crudo){if(crudo){$('production').innerHTML=`<div class="production-item" style="grid-column:1/-1;border:0"><span>Lectura de Crudo</span><strong>Sin porcentaje de producción</strong><small>La fuente registra cantidades de defectos. No demuestra equivalencia con el denominador de Costura + Maquila ni una unidad homogénea.</small></div>`;return;}
 const delta=prior&&prior.rate!==null&&current.rate!==null?current.rate-prior.rate:null;const prevText=delta===null?'—':(delta>=0?'+':'')+delta.toFixed(2)+' pp';$('production').innerHTML=[['Producción Costura',fmt(current.costura),'Campo Cantidad · incluye 2DAS3RAS'],['Producción Maquila',fmt(current.maquila),'Campo InventQty · sin sumar Consumo'],['Producción total',fmt(current.den),'Periodo + modelo + tamaño + color'],['Cantidad de segundas',fmt(current.total),'Segundas Costura · producto terminado'],['Variación mensual',prevText,prior?'Mes anterior: '+pct(prior.rate):'Selecciona un mes para comparar']].map(([l,v,n])=>`<div class="production-item"><span>${l}</span><strong>${v}</strong><small>${n}</small></div>`).join('');}
function lineChart(points,target,crudo){if(!points.length||!points.some(p=>p.value!==null))return'<div class="empty">Sin denominador para calcular la tendencia del segmento.</div>';const width=650,height=240,left=46,top=15,bottom=35,right=15;const max=Math.max(...points.map(p=>p.value||0),crudo?0:target)*1.15||1;const px=i=>left+i/Math.max(points.length-1,1)*(width-left-right),py=v=>height-bottom-(v/max)*(height-bottom-top);const ticks=[0,.25,.5,.75,1].map(t=>{let v=t*max,y=py(v);return`<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" stroke="#e6edf3"/><text x="${left-9}" y="${y+4}" text-anchor="end">${crudo?fmt(Math.round(v)):v.toFixed(1)+'%'}</text>`;}).join('');let path='',open=false;points.forEach((p,i)=>{if(p.value===null){open=false;return;}path+=(open?' L':' M')+px(i)+' '+py(p.value);open=true;});const dots=points.map((p,i)=>p.value===null?'':`<circle cx="${px(i)}" cy="${py(p.value)}" r="${points.length>35?2:3.5}" fill="#27618a"><title>${p.date}: ${crudo?fmt(p.qty):pct(p.value)} · cantidad ${fmt(p.qty)}${crudo?'':' / producción '+fmt(p.den)}</title></circle>`).join('');const step=Math.max(1,Math.ceil(points.length/7));const labels=points.map((p,i)=>i%step===0||i===points.length-1?`<text x="${px(i)}" y="${height-9}" text-anchor="middle">${escape(p.date.length===7?p.date.slice(5):p.date.slice(8)+'/'+p.date.slice(5,7))}</text>`:'').join('');return`<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Tendencia de ${crudo?'cantidad':'porcentaje'}: ${escape(points.filter(p=>p.value!==null).map(p=>p.date+' '+(crudo?fmt(p.qty):pct(p.value))).join('; '))}">${ticks}${crudo?'':`<line x1="${left}" y1="${py(target)}" x2="${width-right}" y2="${py(target)}" stroke="#bf6869" stroke-dasharray="5 5"/>`}<path d="${path}" fill="none" stroke="#27618a" stroke-width="2.5"/>${dots}${labels}</svg><div class="legend"><span><i></i>${crudo?'Cantidad reportada':'% de segundas'}</span>${crudo?'':'<span><i class="goal"></i>Máximo '+target.toFixed(2)+'%</span>'}</div>`;}
function bars(groups,total,limit=8){if(!groups.length)return'<div class="empty">Sin registros para esta selección.</div>';const max=groups[0][1]||1;let cumulative=0;return groups.slice(0,limit).map(([name,qty])=>{cumulative+=qty;return`<div class="bar-row"><div class="bar-label">${escape(name||'Sin dato')}<div class="bar-small">${total>0?(qty/total*100).toFixed(1):'0'}% · acum. ${total>0?(cumulative/total*100).toFixed(1):'0'}%</div></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,qty/max*100)}%"></div></div><div class="bar-num">${fmt(qty)}</div></div>`;}).join('');}
const panel=(title,sub,html,extra='')=>`<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p class="panel-sub">${sub}</p></div>${extra}</div>${html}</section>`;
function table(head,rows){return`<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th scope="col">${escape(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((c,i)=>`<td${i>0?' class="number"':''}>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}" class="empty">Sin registros para esta selección.</td></tr>`}</tbody></table></div>`;}
function matrix(rows,index){const names=group(rows,index).slice(0,6).map(x=>x[0]),defs=group(rows,4).slice(0,4).map(x=>x[0]);const values=new Map();for(const r of rows){const k=JSON.stringify([r[index],r[4]]);values.set(k,(values.get(k)||0)+r[5]);}const max=Math.max(1,...values.values());return`<div class="table-wrap"><table><thead><tr><th>${index===1?'Modelo':'Color'}</th>${defs.map(d=>`<th>${escape(d)}</th>`).join('')}<th>Total</th></tr></thead><tbody>${names.map(n=>`<tr><td>${escape(n||'Sin dato')}</td>${defs.map(d=>{const v=values.get(JSON.stringify([n,d]))||0;return`<td class="heat" style="background:rgba(39,97,138,${v/max*.22})">${v?fmt(v):'—'}</td>`;}).join('')}<td class="number">${fmt(sum(rows.filter(r=>r[index]===n)))}</td></tr>`).join('')}</tbody></table></div>`;}
function visuals(crudo){const target=LIMITS[fixedDepartment()]||1.6,trend=getTrend(current.rows,current.production,granularity,crudo);const picker=`<label class="field" style="max-width:105px;min-width:90px"><span class="sr-only">Agrupación temporal</span><select id="granularity" aria-label="Agrupación temporal">${[['day','Día'],['week','Semana'],['month','Mes']].map(([k,l])=>`<option value="${k}"${granularity===k?' selected':''}>${l}</option>`).join('')}</select></label>`;$('visuals').innerHTML=panel(crudo?'Tendencia de Crudo':'Tendencia de segundas',crudo?'Cantidad del campo original · sin denominador':'Segundas / producción del segmento · periodos con datos',lineChart(trend,target,crudo),picker)+panel('Pareto de defectos','Mayor cantidad · participación y acumulado',bars(group(current.rows,4),current.total));$('granularity').onchange=e=>{granularity=e.target.value;render();};
 const rates=modelRates(current.rows,current.production).slice(0,12);let ratesTable=table(['Modelo','Segundas','Producción','%'],rates.map(r=>[escape(r.name),fmt(r.qty),fmt(r.den),pct(r.rate)]));$('crosses').innerHTML=crudo?panel('Defectos por modelo','Principales modelos del segmento',bars(group(current.rows,1),current.total))+panel('Defectos por localidad / telar','Cantidad registrada en cada localidad',bars(group(current.rows,11),current.total))+panel('Defectos por turno','Turno Tejido registrado en la fuente',bars(group(current.rows,10),current.total))+panel('Modelo × defecto','6 modelos y 4 defectos principales',matrix(current.rows,1)):panel('Segundas y % por modelo','El denominador conserva periodo, tamaño y color; no filtra por defecto',ratesTable)+panel('Segundas por modelo','Cantidad y concentración del segmento',bars(group(current.rows,1),current.total))+panel('Modelo × defecto','6 modelos y 4 defectos principales',matrix(current.rows,1))+panel('Color × defecto','6 colores y 4 defectos principales',matrix(current.rows,3));return trend;}
function alerts(crudo,trend){const list=alertRules(current,prior,{crudo,target:LIMITS[fixedDepartment()]||1.6,label:fixedDepartment()||'GLOBAL',trend});
 if(!crudo&&filters.period==='2026-09'&&!filters.model&&!filters.size&&!filters.color&&!filters.defect&&!filters.department&&!fixedDepartment())list.push({kind:'info',title:'CONCILIACIÓN CON EXCEL',text:'Septiembre: 26,686 / 1,000,316 = 2.66775699%. Coincide con %Segundas!AG8:AG10.'});
 // Recurrence is restricted to the same visible selection and actual weeks.
 const weekly=new Map();for(const r of current.rows){const k=week(r[0]);if(!weekly.has(k))weekly.set(k,[]);weekly.get(k).push(r);}const weeks=[...weekly.keys()].sort().slice(-4);
 if(weeks.length===4){const d0=new Date(weeks[0]+'T12:00:00Z'),d3=new Date(weeks[3]+'T12:00:00Z');if((d3-d0)/86400000===21){const top=weeks.map(w=>new Set(group(weekly.get(w),4).slice(0,5).map(x=>x[0])));for(const d of top[0])if(top.every(s=>s.has(d)))list.push({kind:'warning',title:'RECURRENCIA · '+d.toUpperCase(),text:`Permanece entre los cinco principales defectos durante cuatro semanas consecutivas (${weeks[0]} a ${weeks[3]}).`});}}
 const cross=new Map();for(const r of current.rows){const key=JSON.stringify([r[1],r[4]]);cross.set(key,(cross.get(key)||0)+r[5]);}const first=[...cross].sort((a,b)=>b[1]-a[1])[0];if(first&&current.total>0&&first[1]/current.total>=.1){const[m,d]=JSON.parse(first[0]);list.push({kind:'info',title:'MODELO × DEFECTO',text:`${d} en ${m} concentra ${(first[1]/current.total*100).toFixed(1)}% de la cantidad del segmento (${fmt(first[1])}).`});}
 $('alerts').innerHTML=`<h2>Alertas detectadas</h2><p class="panel-sub">Reglas matemáticas · detección y evidencia · sin causas ni recomendaciones</p><div class="alert-list">${list.length?list.map(a=>`<article class="alert ${a.kind}"><b>${escape(a.title)}</b>${escape(a.text)}</article>`).join(''):'<article class="alert info"><b>SIN ALERTAS DETECTADAS</b>No se activaron las reglas con los datos del segmento seleccionado.</article>'}</div><details class="audit-note" style="margin-top:15px"><summary>Reglas de detección</summary><p>Límite: porcentaje mayor a la meta. Tendencia: aumento estricto en los tres últimos periodos con datos visibles. Defecto: incremento ≥30% frente al mes anterior, con base positiva y al menos 5 unidades actuales. Concentración: tres modelos acumulan ≥50%. Modelo × defecto: un cruce acumula ≥10%. Recurrencia: entre los cinco principales defectos en cuatro semanas consecutivas. La comparación mensual exige un mes seleccionado.</p></details>`;}
function details(crudo){const perPage=50,total=current.rows.length,maxPage=Math.max(0,Math.ceil(total/perPage)-1);page=Math.min(page,maxPage);const rows=current.rows.slice(page*perPage,(page+1)*perPage);const headers=crudo?['Fecha','Modelo','Defecto','Cantidad','Turno','Localidad / Telar','Salón','Referencia','Archivo fuente','Fila fuente']:['Fecha','Modelo','Código','Tamaño','Color','Defecto','Departamento','Cantidad','Origen / maquilador','Archivo fuente','Fila fuente'];$('details').innerHTML=`<div class="panel-header"><div><h2>Detalle del histórico</h2><p class="panel-sub">${fmt(total)} registros · fuente: ${crudo?'Segundas Crudo':'SEGUNDAS'} · filas originales conservadas</p></div><span class="period-badge">${escape(monthLabel(filters.period))}</span></div>`+table(headers,rows.map(r=>crudo?[escape(r[0]),escape(r[1]),escape(r[4]),fmt(r[5]),escape(r[10]),escape(r[11]),escape(r[12]),escape(r[8]),escape(r[14]||'Segundas 2026.xlsx'),r[9]]:[escape(r[0]),escape(r[1]),escape(r[7]),escape(r[2]),escape(r[3]),escape(r[4]),department(r),fmt(r[5]),escape(r[8]),escape(r[14]||'Segundas 2026.xlsx'),r[9]]))+`<div class="table-controls"><span>Página ${page+1} de ${maxPage+1}</span><button class="button" id="prev-page"${page===0?' disabled':''}>Anterior</button><button class="button" id="next-page"${page===maxPage?' disabled':''}>Siguiente</button></div>`;$('prev-page').onclick=()=>{page--;details(crudo);};$('next-page').onclick=()=>{page++;details(crudo);};}
function render(){nav();$('page-title').textContent=VIEWS[view][1];$('page-subtitle').textContent=VIEWS[view][2];filterUi();const crudo=view==='crudo';current=getMetrics(allBase(),crudo?[]:data.production,effective());const prev=previousMonth(filters.period);prior=prev&&allBase().some(r=>r[0].startsWith(prev))?getMetrics(allBase(),crudo?[]:data.production,effective({...filters,period:prev})):null;
const unclassified=!crudo?current.byDepartment['SIN CLASIFICAR']:0;let note=crudo?'Crudo se analiza de forma independiente. La cantidad reportada no se convierte en % de producción.':filters.period==='2026-09'?'Septiembre conciliado con el Excel: la base reproduce la producción y las segundas históricas.':'Histórico reconstruido con la regla conciliada en septiembre. Los demás meses no cuentan con un control de % guardado equivalente.';if(unclassified)note+=` ${fmt(unclassified)} segundas tienen defecto identificado y están pendientes de asignación departamental en el catálogo del Site.`;if(current.den===0&&!crudo)note+=' No existe producción coincidente para este segmento.';$('notice').textContent=note;$('notice').className='notice'+(unclassified||(!crudo&&current.den===0)?' warn':'');renderKpis(crudo);renderProduction(crudo);const trend=visuals(crudo);alerts(crudo,trend);details(crudo);$('dashboard').setAttribute('aria-busy','false');}
function navigate(next){if(!VIEWS[next])throw Error('Vista no válida');const changed=(view==='crudo')!==(next==='crudo');view=next;if(changed)filters={period:filters.period};page=0;location.hash=next;render();}
document.addEventListener('click',e=>{const n=e.target.closest('[data-view]');if(n&&data.seconds)navigate(n.dataset.view);});window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(VIEWS[v]&&v!==view&&data.seconds)navigate(v);});
async function init(){try{const keys=['seconds','costura','maquila','crudo','reference','audit'];const responses=await Promise.all(keys.map(async k=>{const r=await fetch(k+'.json');if(!r.ok)throw Error('No se pudo cargar '+k);return[k,await r.json()];}));for(const[k,v]of responses)if(k==='audit')audit=v;else data[k]=decode(v);data.production=[...data.costura,...data.maquila];filters.period=allBase().reduce((latest,r)=>r[0]>latest?r[0]:latest,'').slice(0,7)||'all';render();if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_quality_indicators',description:'Consultar los indicadores calculados para la vista y filtros actuales de Towell.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view,filters,quantity:current?.total,production:current?.den,percent:current?.rate,source:'Segundas 2026.xlsx'})});document.modelContext.registerTool({name:'set_quality_view',description:'Cambiar la vista de consulta de calidad; no modifica el histórico.',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(VIEWS)}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='view')||!VIEWS[input.view])throw Error('Vista no válida');navigate(input.view);return{view};}});}catch(e){console.info('Consulta asistida no disponible',e);}}}catch(e){$('notice').className='notice warn';$('notice').textContent='No se pudo cargar la base histórica. Vuelve a cargar la página para intentar de nuevo.';$('dashboard').setAttribute('aria-busy','false');console.error(e);}}
init();
